(window.__qhadithX=window.__qhadithX||{})[65]={"1":[{"c":"Sunan Abu Dawud","r":"Hadith 2202","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2202","x":"‘Abd Allah bin Ka’b reported \"I heard Ka’ab bin Malik. He then narrated his story about the battle of Tabuk.(Narrating the story) he added \"When forty out of fifty days passed\", the messenger of the Apostle of Allaah(ﷺ) came and said \"The Apostle of Allaah(ﷺ) has commanded you to keep away from your wife. He said \"So, I (Ka’b bin Malik)\" said \"Should I divorce her or what should I do? He said \"No, but only keep away from her and do not go near her\". So, I said to my wife \"Go to your people and live with them until Allaah, the exalted makes a decision in this matter.\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ، وَسُلَيْمَانُ بْنُ دَاوُدَ، قَالاَ أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، أَخْبَرَنِي عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ، أَنَّ عَبْدَ اللَّهِ بْنَ كَعْبٍ، - وَكَانَ قَائِدَ كَعْبٍ مِنْ بَنِيهِ حِينَ عَمِيَ - قَالَ سَمِعْتُ كَعْبَ بْنَ مَالِكٍفَسَاقَ قِصَّتَهُ فِي تَبُوكَ قَالَ حَتَّى إِذَا مَضَتْ أَرْبَعُونَ مِنَ الْخَمْسِينَ إِذَا رَسُولُ رَسُولِ اللَّهِ صلى الله عليه وسلم يَأْتِي فَقَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم يَأْمُرُكَ أَنْ تَعْتَزِلَ امْرَأَتَكَ ‏.‏ قَالَ فَقُلْتُ أُطَلِّقُهَا أَمْ مَاذَا أَفْعَلُ قَالَ لاَ بَلِ اعْتَزِلْهَا فَلاَ تَقْرَبَنَّهَا ‏.‏ فَقُلْتُ لاِمْرَأَتِي الْحَقِي بِأَهْلِكِ فَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللَّهُ سُبْحَانَهُ فِي هَذَا الأَمْرِ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1480n","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1480n","x":"Abu Ishaq reported:\n\nI was with al-Aswad b. Yazid sitting in the great mosque, and there was with us al-Sha'bi, and he narrated the narration of Fatima bint Qais (Allah be pleased with her) that Allah's Messenger (ﷺ) did not make any provision for lodging and maintenance allowance for her. Al-Aswad caught hold of some pebbles in his fist and he threw them towards him saying: Woe be to thee, you narrate like it, whereas Umar said: We cannot abandon the Book of Allah and the Sunnah of our Apostle (ﷺ) for the words of a woman. We do not know whether she remembers that or she forgets. For her, there is a provision of lodging and maintenance allowance. Allah, the Exalted and Majestic, said:\" Turn them not from their houses nor should they themselves go forth unless they commit an open indecency\" (lxv. 1).","ar":"وَحَدَّثَنَاهُ مُحَمَّدُ بْنُ عَمْرِو بْنِ جَبَلَةَ، حَدَّثَنَا أَبُو أَحْمَدَ، حَدَّثَنَا عَمَّارُ بْنُ رُزَيْقٍ، عَنْ أَبِي إِسْحَاقَ، قَالَ كُنْتُ مَعَ الأَسْوَدِ بْنِ يَزِيدَ جَالِسًا فِي الْمَسْجِدِ الأَعْظَمِ وَمَعَنَا الشَّعْبِيُّ فَحَدَّثَ الشَّعْبِيُّ بِحَدِيثِ فَاطِمَةَ بِنْتِ قَيْسٍ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمْ يَجْعَلْ لَهَا سُكْنَى وَلاَ نَفَقَةً ثُمَّ أَخَذَ الأَسْوَدُ كَفًّا مِنْ حَصًى فَحَصَبَهُ بِهِ ‏.‏ فَقَالَ وَيْلَكَ تُحَدِّثُ بِمِثْلِ هَذَا قَالَ عُمَرُ لاَ نَتْرُكُ كِتَابَ اللَّهِ وَسُنَّةَ نَبِيِّنَا صلى الله عليه وسلم لِقَوْلِ امْرَأَةٍ لاَ نَدْرِي لَعَلَّهَا حَفِظَتْ أَوْ نَسِيَتْ لَهَا السُّكْنَى وَالنَّفَقَةُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ لاَ تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلاَ يَخْرُجْنَ إِلاَّ أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ‏}‏ ‏.‏","v":[]}],"2":[{"c":"Al-Adab Al-Mufrad","r":"Book 28, Hadith 489","u":"https://quranx.com/Hadith/Adab/English/Book-28/Hadith-489","x":"Abu'd-Duha said:\n\n\"Masruq and Shutayr ibn Shakal met in the mosque. The people sitting in circles in the mosque moved towards them. Masruq said, 'I can only think that these people are gathering around us in order to hear good from us. If you relate from 'Abdullah, I will confirm you. If I relate from 'Abdullah, you can confirm me.' He said, 'Abu 'A'isha, relate!' He said, 'Did you hear 'Abdullah say, \"The eyes commit fornication. The hands commit fornication. The feet commit fornication, and then the genitals either confirm or deny that?\"' 'Yes,' he replied, 'I have heard it.' He said, 'Did you hear 'Abdullah say, \"There is no ayat in the Qur'an which is greater in combining the halal and the haram and the command and the prohibition than this ayat: 'Indeed Allah commands to justice and doing good and giving to relatives' (16.90)?\"' 'Yes,' he replied, 'I have heard it.' He said, 'Did you hear 'Abdullah say, \"There is no ayat in the Qur'an swifter in bringing relief than His words, \"Whoever has taqwa of Allah - He will give him a way out\" (65:2)?' 'Yes,' he replied, 'I have heard it.' He said, 'Did you hear 'Abdullah say, \"There is no ayat in the Qur'an stronger in entrusting things to Allah than His words, \"My slaves, you have transgressed against yourselves, do not despair of the mercy of Allah\" (39:53)?' 'Yes,' he replied, 'I heard that.'\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، قَالَ‏:‏ حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ عَاصِمٍ، عَنْ أَبِي الضُّحَى قَالَ‏:‏ اجْتَمَعَ مَسْرُوقٌ وَشُتَيْرُ بْنُ شَكَلٍ فِي الْمَسْجِدِ، فَتَقَوَّضَ إِلَيْهِمَا حِلَقُ الْمَسْجِدِ، فَقَالَ مَسْرُوقٌ‏:‏ لاَ أَرَى هَؤُلاَءِ يَجْتَمِعُونَ إِلَيْنَا إِلاَّ لِيَسْتَمِعُوا مِنَّا خَيْرًا، فَإِمَّا أَنْ تُحَدِّثَ عَنْ عَبْدِ اللهِ فَأُصَدِّقَكَ أَنَا، وَإِمَّا أَنْ أُحَدِّثَ عَنْ عَبْدِ اللهِ فَتُصَدِّقَنِي‏؟‏ فَقَالَ‏:‏ حَدِّثْ يَا أَبَا عَائِشَةَ، قَالَ‏:‏ هَلْ سَمِعْتَ عَبْدَ اللهِ يَقُولُ‏:‏ الْعَيْنَانِ يَزْنِيَانِ، وَالْيَدَانِ يَزْنِيَانِ، وَالرِّجْلاَنِ يَزْنِيَانِ، وَالْفَرْجُ يُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ‏؟‏ فَقَالَ‏:‏ نَعَمْ، قَالَ‏:‏ وَأَنَا سَمِعْتُهُ، قَالَ‏:‏ فَهَلْ سَمِعْتَ عَبْدَ اللهِ يَقُولُ‏:‏ مَا فِي الْقُرْآنِ آيَةٌ أَجْمَعَ لِحَلاَلٍ وَحَرَامٍ وَأَمْرٍ وَنَهْيٍ، مِنْ هَذِهِ الْآيَةِ‏:‏ ‏{‏إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالإِحْسَانِ وَإِيتَاءِ ذِي الْقُرْبَى‏}‏‏؟‏ قَالَ‏:‏ نَعَمْ، قَالَ‏:‏ وَأَنَا قَدْ سَمِعْتُهُ، قَالَ‏:‏ فَهَلْ سَمِعْتَ عَبْدَ اللهِ يَقُولُ‏:‏ مَا فِي الْقُرْآنِ آيَةٌ أَسْرَعَ فَرَجًا مِنْ قَوْلِهِ‏:‏ ‏{‏وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا‏}‏‏؟‏ قَالَ‏:‏ نَعَمْ، قَالَ‏:‏ وَأَنَا قَدْ سَمِعْتُهُ، قَالَ‏:‏ فَهَلْ سَمِعْتَ عَبْدَ اللهِ يَقُولُ‏:‏ مَا فِي الْقُرْآنِ آيَةٌ أَشَدَّ تَفْوِيضًا مِنْ قَوْلِهِ‏:‏ ‏{‏يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لاَ تَقْنَطُوا‏}‏ مِنْ رَحْمَةِ اللهِ‏؟‏ قَالَ‏:‏ نَعَمْ، قَالَ‏:‏ وَأَنَا سَمِعْتُهُ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 5, Book 37, Hadith 4220","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-37/Hadith-4220","x":"It was narrated from Abu Dharr that the Messenger of Allah (ﷺ) said:\n\n\"I know a word – (one of the narrators) ‘Uthman said: \"a Verse\" – which if all the people followed it, it would suffice them.\" They said: \"O Messenger of Allah, which Verse?\" He said: \"And whosoever fears Allah, He will make a way out for him.\" [65:2]","ar":"حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، وَعُثْمَانُ بْنُ أَبِي شَيْبَةَ، قَالاَ حَدَّثَنَا الْمُعْتَمِرُ بْنُ سُلَيْمَانَ، عَنْ كَهْمَسِ بْنِ الْحَسَنِ، عَنْ أَبِي السَّلِيلِ، ضُرَيْبِ بْنِ نُقَيْرٍ عَنْ أَبِي ذَرٍّ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\"‏ إِنِّي لأَعْرِفُ كَلِمَةً - وَقَالَ عُثْمَانُ آيَةً - لَوْ أَخَذَ النَّاسُ كُلُّهُمْ بِهَا لَكَفَتْهُمْ ‏\"‏ ‏.‏ قَالُوا يَا رَسُولَ اللَّهِ أَيَّةُ آيَةٍ قَالَ ‏\"‏ وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ‏\"‏ ‏.‏","v":[]}],"4":[{"c":"Sunan Abu Dawud","r":"Hadith 2121","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2121","x":"Narrated 'Aishah:\n\nThe Messenger of Allah (ﷺ) married me when I was seven years old. The narrator Sulaiman said: or Six years. He had intercourse with me when I was nine years old.","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، وَأَبُو كَامِلٍ قَالاَ حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ تَزَوَّجَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَنَا بِنْتُ سَبْعٍ - قَالَ سُلَيْمَانُ أَوْ سِتٍّ - وَدَخَلَ بِي وَأَنَا بِنْتُ تِسْعٍ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4933","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4933","x":"Narrated Aisha, Ummul Mu'minin:\n\nThe Messenger of Allah (ﷺ) married me when I was seven or six. When we came to Medina, some women came. according to Bishr's version: Umm Ruman came to me when I was swinging. They took me, made me prepared and decorated me. I was then brought to the Messenger of Allah (ﷺ), and he took up cohabitation with me when I was nine. She halted me at the door, and I burst into laughter. Abu Dawud said: That is to say: I menstruated, and I was brought in a house, and there were some women of the Ansari in it. They said: With good luck and blessing. The tradition of one of them has been included in the other.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادٌ، ح وَحَدَّثَنَا بِشْرُ بْنُ خَالِدٍ، حَدَّثَنَا أَبُو أُسَامَةَ، قَالاَ حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم تَزَوَّجَنِي وَأَنَا بِنْتُ سَبْعِ سِنِينَ فَلَمَّا قَدِمْنَا الْمَدِينَةَ أَتَيْنَ نِسْوَةٌ - وَقَالَ بِشْرٌ فَأَتَتْنِي أُمُّ رُومَانَ - وَأَنَا عَلَى أُرْجُوحَةٍ فَذَهَبْنَ بِي وَهَيَّأْنَنِي وَصَنَعْنَنِي فَأُتِيَ بِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَبَنَى بِي وَأَنَا ابْنَةُ تِسْعٍ فَوَقَفَتْ بِي عَلَى الْبَابِ فَقُلْتُ هِيهْ هِيهْ - قَالَ أَبُو دَاوُدَ أَىْ تَنَفَّسَتْ - فَأُدْخِلْتُ بَيْتًا فَإِذَا فِيهِ نِسْوَةٌ مِنَ الأَنْصَارِ فَقُلْنَ عَلَى الْخَيْرِ وَالْبَرَكَةِ ‏.‏ دَخَلَ حَدِيثُ أَحَدِهِمَا فِي الآخَرِ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4935","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4935","x":"Narrated Aisha, Ummul Mu'minin:\n\nWhen we came to Medina, the women came to me when I was playing on the swing, and my hair were up to my ears. They brought me, prepared me, and decorated me. Then they brought me to the Messenger of Allah (ﷺ) and he took up cohabitation with me, when I was nine.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادٌ، أَخْبَرَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، رضى الله عنها، قَالَتْ فَلَمَّا قَدِمْنَا الْمَدِينَةَ جَاءَنِي نِسْوَةٌ وَأَنَا أَلْعَبُ عَلَى أُرْجُوحَةٍ وَأَنَا مُجَمَّمَةٌ فَذَهَبْنَ بِي فَهَيَّأْنَنِي وَصَنَّعْنَنِي ثُمَّ أَتَيْنَ بِي رَسُولَ اللَّهِ صلى الله عليه وسلم فَبَنَى بِي وَأَنَا ابْنَةُ تِسْعِ سِنِينَ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3894","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3894","x":"Narrated Aisha:\n\nThe Prophet (ﷺ) engaged me when I was a girl of six (years). We went to Medina and stayed at the home of Bani-al-Harith bin Khazraj. Then I got ill and my hair fell down. Later on my hair grew (again) and my mother, Um Ruman, came to me while I was playing in a swing with some of my girl friends. She called me, and I went to her, not knowing what she wanted to do to me. She caught me by the hand and made me stand at the door of the house. I was breathless then, and when my breathing became Allright, she took some water and rubbed my face and head with it. Then she took me into the house. There in the house I saw some Ansari women who said, \"Best wishes and Allah's Blessing and a good luck.\" Then she entrusted me to them and they prepared me (for the marriage). Unexpectedly Allah's Apostle came to me in the forenoon and my mother handed me over to him, and at that time I was a girl of nine years of age.","ar":"حَدَّثَنِي فَرْوَةُ بْنُ أَبِي الْمَغْرَاءِ، حَدَّثَنَا عَلِيُّ بْنُ مُسْهِرٍ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ تَزَوَّجَنِي النَّبِيُّ صلى الله عليه وسلم وَأَنَا بِنْتُ سِتِّ سِنِينَ، فَقَدِمْنَا الْمَدِينَةَ فَنَزَلْنَا فِي بَنِي الْحَارِثِ بْنِ خَزْرَجٍ، فَوُعِكْتُ فَتَمَرَّقَ شَعَرِي فَوَفَى جُمَيْمَةً، فَأَتَتْنِي أُمِّي أُمُّ رُومَانَ وَإِنِّي لَفِي أُرْجُوحَةٍ وَمَعِي صَوَاحِبُ لِي، فَصَرَخَتْ بِي فَأَتَيْتُهَا لاَ أَدْرِي مَا تُرِيدُ بِي فَأَخَذَتْ بِيَدِي حَتَّى أَوْقَفَتْنِي عَلَى باب الدَّارِ، وَإِنِّي لأَنْهَجُ، حَتَّى سَكَنَ بَعْضُ نَفَسِي، ثُمَّ أَخَذَتْ شَيْئًا مِنْ مَاءٍ فَمَسَحَتْ بِهِ وَجْهِي وَرَأْسِي ثُمَّ أَدْخَلَتْنِي الدَّارَ فَإِذَا نِسْوَةٌ مِنَ الأَنْصَارِ فِي الْبَيْتِ فَقُلْنَ عَلَى الْخَيْرِ وَالْبَرَكَةِ، وَعَلَى خَيْرِ طَائِرٍ‏.‏ فَأَسْلَمَتْنِي إِلَيْهِنَّ فَأَصْلَحْنَ مِنْ شَأْنِي، فَلَمْ يَرُعْنِي إِلاَّ رَسُولُ اللَّهِ صلى الله عليه وسلم ضُحًى، فَأَسْلَمَتْنِي إِلَيْهِ، وَأَنَا يَوْمَئِذٍ بِنْتُ تِسْعِ سِنِينَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3896","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3896","x":"Narrated Hisham's father:\n\nKhadija died three years before the Prophet (ﷺ) departed to Medina. He stayed there for two years or so and then he married `Aisha when she was a girl of six years of age, and he consumed that marriage when she was nine years old.","ar":"حَدَّثَنِي عُبَيْدُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، قَالَ تُوُفِّيَتْ خَدِيجَةُ قَبْلَ مَخْرَجِ النَّبِيِّ صلى الله عليه وسلم إِلَى الْمَدِينَةِ بِثَلاَثِ سِنِينَ، فَلَبِثَ سَنَتَيْنِ أَوْ قَرِيبًا مِنْ ذَلِكَ، وَنَكَحَ عَائِشَةَ وَهْىَ بِنْتُ سِتِّ سِنِينَ، ثُمَّ بَنَى بِهَا وَهْىَ بِنْتُ تِسْعِ سِنِينَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5133","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5133","x":"Narrated `Aisha:\n\nthat the Prophet (ﷺ) married her when she was six years old and he consummated his marriage when she was nine years old, and then she remained with him for nine years (i.e., till his death).","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا سُفْيَانُ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ ـ رضى الله عنها ـ أَنَّ النَّبِيَّ صلى الله عليه وسلم تَزَوَّجَهَا وَهْىَ بِنْتُ سِتِّ سِنِينَ، وَأُدْخِلَتْ عَلَيْهِ وَهْىَ بِنْتُ تِسْعٍ، وَمَكَثَتْ عِنْدَهُ تِسْعًا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5134","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5134","x":"Narrated `Aisha:\n\nthat the Prophet (ﷺ) married her when she was six years old and he consummated his marriage when she was nine years old. Hisham said: I have been informed that `Aisha remained with the Prophet (ﷺ) for nine years (i.e. till his death).","ar":"حَدَّثَنَا مُعَلَّى بْنُ أَسَدٍ، حَدَّثَنَا وُهَيْبٌ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم تَزَوَّجَهَا وَهْىَ بِنْتُ سِتِّ سِنِينَ، وَبَنَى بِهَا وَهْىَ بِنْتُ تِسْعِ سِنِينَ‏.‏ قَالَ هِشَامٌ وَأُنْبِئْتُ أَنَّهَا كَانَتْ عِنْدَهُ تِسْعَ سِنِينَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5158","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5158","x":"Narrated 'Urwa:\n\nThe Prophet (ﷺ) wrote the (marriage contract) with `Aisha while she was six years old and consummated his marriage with her while she was nine years old and she remained with him for nine years (i.e. till his death).","ar":"حَدَّثَنَا قَبِيصَةُ بْنُ عُقْبَةَ، حَدَّثَنَا سُفْيَانُ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ عُرْوَةَ، تَزَوَّجَ النَّبِيُّ صلى الله عليه وسلم عَائِشَةَ وَهْىَ ابْنَةُ سِتٍّ وَبَنَى بِهَا وَهْىَ ابْنَةُ تِسْعٍ وَمَكَثَتْ عِنْدَهُ تِسْعًا‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 3, Book 9, Hadith 1876","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-3/Book-9/Hadith-1876","x":"It was narrated that:\n\nAishah said: \"The Messenger of Allah married me when I was six years old. Then we came to Al-Madinah and settled among Banu Harith bin Khazraj. I became ill and my hair fell out, then it grew back and became abundant. My mother Umm Ruman came to me while I was on an Urjuhah with some of my friends, and called for me. I went to her, and I did not know what she wanted. She took me by the hand and made me stand at the door of the house, and I was panting. When I got my breath back, she took some water and wiped my face and head, and led me into the house. There were some woman of the Ansar inside the house, and they said: 'With blessings and good fortune (from Allah).' (My mother) handed me over to them and they tidied me up. And suddenly I saw the Messenger of Allah in the morning. And she handed me over to him and I was at that time, nine years old.\"","ar":"حَدَّثَنَا سُوَيْدُ بْنُ سَعِيدٍ، حَدَّثَنَا عَلِيُّ بْنُ مُسْهِرٍ، حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ تَزَوَّجَنِي رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ وَأَنَا بِنْتُ سِتِّ سِنِينَ فَقَدِمْنَا الْمَدِينَةَ فَنَزَلْنَا فِي بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ فَوُعِكْتُ فَتَمَرَّقَ شَعَرِي حَتَّى وَفَى لَهُ جُمَيْمَةٌ فَأَتَتْنِي أُمِّي أُمُّ رُومَانَ وَإِنِّي لَفِي أُرْجُوحَةٍ وَمَعِي صَوَاحِبَاتٌ لِي فَصَرَخَتْ بِي فَأَتَيْتُهَا وَمَا أَدْرِي مَا تُرِيدُ فَأَخَذَتْ بِيَدِي فَأَوْقَفَتْنِي عَلَى بَابِ الدَّارِ وَإِنِّي لأَنْهَجُ حَتَّى سَكَنَ بَعْضُ نَفَسِي ثُمَّ أَخَذَتْ شَيْئًا مِنْ مَاءٍ فَمَسَحَتْ بِهِ عَلَى وَجْهِي وَرَأْسِي ثُمَّ أَدْخَلَتْنِي الدَّارَ فَإِذَا نِسْوَةٌ مِنَ الأَنْصَارِ فِي بَيْتٍ فَقُلْنَ عَلَى الْخَيْرِ وَالْبَرَكَةِ وَعَلَى خَيْرِ طَائِرٍ ‏.‏ فَأَسْلَمَتْنِي إِلَيْهِنَّ فَأَصْلَحْنَ مِنْ شَأْنِي فَلَمْ يَرُعْنِي إِلاَّ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ضُحًى ‏.‏ فَأَسْلَمَتْنِي إِلَيْهِ وَأَنَا يَوْمَئِذٍ بِنْتُ تِسْعِ سِنِينَ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 3, Book 9, Hadith 1877","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-3/Book-9/Hadith-1877","x":"It was narrated that:\n\nAbdullah said: \"The Prophet married Aishah when she was seven years old, and consummated the marriage with her when she was nine, and he passed away when she was eighteen.\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ سِنَانٍ، حَدَّثَنَا أَبُو أَحْمَدَ، حَدَّثَنَا إِسْرَائِيلُ، عَنْ أَبِي إِسْحَاقَ، عَنْ أَبِي عُبَيْدَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ تَزَوَّجَ النَّبِيُّ ـ صلى الله عليه وسلم ـ عَائِشَةَ وَهِيَ بِنْتُ سَبْعٍ وَبَنَى بِهَا وَهِيَ بِنْتُ تِسْعٍ وَتُوُفِّيَ عَنْهَا وَهِيَ بِنْتُ ثَمَانِي عَشْرَةَ سَنَةً ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 29, Hadith 1232","u":"https://quranx.com/Hadith/Malik/In-Book/Book-29/Hadith-1232","x":"Yahya related to me from Malik from Ibn Shihab that Said ibn al- Musayyab said, \"The idda of the woman who bleeds constantly is a year.\" Malik said, \"What is done among us about a divorced woman whose periods stop when her husband divorces her is that she waits nine months. If she has not had a period in them, she has an idda of three months. If she has a period before the end of the three months, she accepts the period. If another nine months pass without her having a period, she does an idda of three months. If she has a second period before the end of those three months, she accepts the period. If nine months then pass without a period, she does an idda of three months. If she has a third period, the idda of the period is complete. If she does not have a period, she waits three months, and then she is free to marry. Her husband can return to her before she becomes free to marry unless he made her divorce irrevocable.\" Malik said, \"The sunna with us is that when a man divorces his wife and has the option to return to her, and she does part of her idda and then he returns to her and then parts from her before he has had intercourse with her, she does not add to what has passed of her idda. Her husband has wronged himself and erred if he returned to her and had no need of her.\" Malik said, \"What is done among us is that if a woman becomes a muslim while her husband is a kafir and then he becomes muslim, he is entitled to her as long as she is in her idda. If her idda is finished, he has no access to her. If he remarries her after the end of her idda, however, that is not counted as divorce. Islam removed her from him without divorce.\"","ar":"وَحَدَّثَنِي عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، أَنَّهُ قَالَ عِدَّةُ الْمُسْتَحَاضَةِ سَنَةٌ ‏.‏ قَالَ مَالِكٌ الأَمْرُ عِنْدَنَا فِي الْمُطَلَّقَةِ الَّتِي تَرْفَعُهَا حَيْضَتُهَا حِينَ يُطَلِّقُهَا زَوْجُهَا أَنَّهَا تَنْتَظِرُ تِسْعَةَ أَشْهُرٍ فَإِنْ لَمْ تَحِضْ فِيهِنَّ اعْتَدَّتْ ثَلاَثَةَ أَشْهُرٍ فَإِنْ حَاضَتْ قَبْلَ أَنْ تَسْتَكْمِلَ الأَشْهُرَ الثَّلاَثَةَ اسْتَقْبَلَتِ الْحَيْضَ فَإِنْ مَرَّتْ بِهَا تِسْعَةُ أَشْهُرٍ قَبْلَ أَنْ تَحِيضَ اعْتَدَّتْ ثَلاَثَةَ أَشْهُرٍ فَإِنْ حَاضَتِ الثَّانِيَةَ قَبْلَ أَنْ تَسْتَكْمِلَ الأَشْهُرَ الثَّلاَثَةَ اسْتَقْبَلَتِ الْحَيْضَ فَإِنْ مَرَّتْ بِهَا تِسْعَةُ أَشْهُرٍ قَبْلَ أَنْ تَحِيضَ اعْتَدَّتْ ثَلاَثَةَ أَشْهُرٍ فَإِنْ حَاضَتِ الثَّالِثَةَ كَانَتْ قَدِ اسْتَكْمَلَتْ عِدَّةَ الْحَيْضِ فَإِنْ لَمْ تَحِضِ اسْتَقْبَلَتْ ثَلاَثَةَ أَشْهُرٍ ثُمَّ حَلَّتْ وَلِزَوْجِهَا عَلَيْهَا فِي ذَلِكَ الرَّجْعَةُ قَبْلَ أَنْ تَحِلَّ إِلاَّ أَنْ يَكُونَ قَدْ بَتَّ طَلاَقَهَا ‏.‏ قَالَ مَالِكٌ السُّنَّةُ عِنْدَنَا أَنَّ الرَّجُلَ إِذَا طَلَّقَ امْرَأَتَهُ وَلَهُ عَلَيْهَا رَجْعَةٌ فَاعْتَدَّتْ بَعْضَ عِدَّتِهَا ثُمَّ ارْتَجَعَهَا ثُمَّ فَارَقَهَا قَبْلَ أَنْ يَمَسَّهَا أَنَّهَا لاَ تَبْنِي عَلَى مَا مَضَى مِنْ عِدَّتِهَا وَأَنَّهَا تَسْتَأْنِفُ مِنْ يَوْمَ طَلَّقَهَا عِدَّةً مُسْتَقْبَلَةً وَقَدْ ظَلَمَ زَوْجُهَا نَفْسَهُ وَأَخْطَأَ إِنْ كَانَ ارْتَجَعَهَا وَلاَ حَاجَةَ لَهُ بِهَا ‏.‏ قَالَ مَالِكٌ وَالأَمْرُ عِنْدَنَا أَنَّ الْمَرْأَةَ إِذَا أَسْلَمَتْ وَزَوْجُهَا كَافِرٌ ثُمَّ أَسْلَمَ فَهُوَ أَحَقُّ بِهَا مَا دَامَتْ فِي عِدَّتِهَا فَإِنِ انْقَضَتْ عِدَّتُهَا فَلاَ سَبِيلَ لَهُ عَلَيْهَا وَإِنْ تَزَوَّجَهَا بَعْدَ انْقِضَاءِ عِدَّتِهَا لَمْ يُعَدَّ ذَلِكَ طَلاَقًا وَإِنَّمَا فَسَخَهَا مِنْهُ الإِسْلاَمُ بِغَيْرِ طَلاَقٍ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1422a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1422a","x":"'A'isha (Allah be pleased with her) reported:\n\nAllah's Messenger (ﷺ) married me when I was six years old, and I was admitted to his house at the age of nine. She further said: We went to Medina and I had an attack of fever for a month, and my hair had come down to the earlobes. Umm Ruman (my mother) came to me and I was at that time on a swing along with my playmates. She called me loudly and I went to her and I did not know what she had wanted of me. She took hold of my hand and took me to the door, and I was saying: Ha, ha (as if I was gasping), until the agitation of my heart was over. She took me to a house, where had gathered the women of the Ansar. They all blessed me and wished me good luck and said: May you have share in good. She (my mother) entrusted me to them. They washed my head and embellished me and nothing frightened me. Allah's Messenger (, may peace be upon him) came there in the morning, and I was entrusted to him.","ar":"حَدَّثَنَا أَبُو كُرَيْبٍ، مُحَمَّدُ بْنُ الْعَلاَءِ حَدَّثَنَا أَبُو أُسَامَةَ، ح وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي، شَيْبَةَ قَالَ وَجَدْتُ فِي كِتَابِي عَنْ أَبِي أُسَامَةَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ تَزَوَّجَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم لِسِتِّ سِنِينَ وَبَنَى بِي وَأَنَا بِنْتُ تِسْعِ سِنِينَ ‏.‏ قَالَتْ فَقَدِمْنَا الْمَدِينَةَ فَوُعِكْتُ شَهْرًا فَوَفَى شَعْرِي جُمَيْمَةً فَأَتَتْنِي أُمُّ رُومَانَ وَأَنَا عَلَى أُرْجُوحَةٍ وَمَعِي صَوَاحِبِي فَصَرَخَتْ بِي فَأَتَيْتُهَا وَمَا أَدْرِي مَا تُرِيدُ بِي فَأَخَذَتْ بِيَدِي فَأَوْقَفَتْنِي عَلَى الْبَابِ ‏.‏ فَقُلْتُ هَهْ هَهْ ‏.‏ حَتَّى ذَهَبَ نَفَسِي فَأَدْخَلَتْنِي بَيْتًا فَإِذَا نِسْوَةٌ مِنَ الأَنْصَارِ فَقُلْنَ عَلَى الْخَيْرِ وَالْبَرَكَةِ وَعَلَى خَيْرِ طَائِرٍ ‏.‏ فَأَسْلَمَتْنِي إِلَيْهِنَّ فَغَسَلْنَ رَأْسِي وَأَصْلَحْنَنِي فَلَمْ يَرُعْنِي إِلاَّ وَرَسُولُ اللَّهِ صلى الله عليه وسلم ضُحًى فَأَسْلَمْنَنِي إِلَيْهِ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1422b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1422b","x":"'A'isha (Allah be pleased with her) reported:\n\nAllah's Apostle (ﷺ) married me when I was six years old, and I was admitted to his house when I was nine years old.","ar":"وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى، أَخْبَرَنَا أَبُو مُعَاوِيَةَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، ح وَحَدَّثَنَا ابْنُ نُمَيْرٍ، - وَاللَّفْظُ لَهُ - حَدَّثَنَا عَبْدَةُ، - هُوَ ابْنُ سُلَيْمَانَ - عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ تَزَوَّجَنِي النَّبِيُّ صلى الله عليه وسلم وَأَنَا بِنْتُ سِتِّ سِنِينَ وَبَنَى بِي وَأَنَا بِنْتُ تِسْعِ سِنِينَ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1422c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1422c","x":"'A'isha (Allah be pleased with her) reported that Allah's Apostle (ﷺ) married her when she was seven years old, and he was taken to his house as a bride when she was nine, and her dolls were with her; and when he (the Holy Prophet) died she was eighteen years old.","ar":"وَحَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم تَزَوَّجَهَا وَهْىَ بِنْتُ سَبْعِ سِنِينَ وَزُفَّتْ إِلَيْهِ وَهِيَ بِنْتُ تِسْعِ سِنِينَ وَلُعَبُهَا مَعَهَا وَمَاتَ عَنْهَا وَهِيَ بِنْتُ ثَمَانَ عَشْرَةَ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1422d","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1422d","x":"Narrated 'A'isha :\n\n'A'isha (Allah be pleased with her) reported that Allah's Apostle (ﷺ) married her when she was six years old, and he (the Holy Prophet) took her to his house when she was nine, and when he (the Holy Prophet) died she was eighteen years old","ar":"وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ، وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ وَأَبُو كُرَيْبٍ قَالَ يَحْيَى وَإِسْحَاقُ أَخْبَرَنَا وَقَالَ الآخَرَانِ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنِ الأَسْوَدِ، عَنْ عَائِشَةَ، قَالَتْ تَزَوَّجَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم وَهْىَ بِنْتُ سِتٍّ وَبَنَى بِهَا وَهْىَ بِنْتُ تِسْعٍ وَمَاتَ عَنْهَا وَهْىَ بِنْتُ ثَمَانَ عَشْرَةَ ‏.‏","v":[]},{"c":"Sunan an-Nasa'i","r":"Volume 4, Book 26, Hadith 3257","u":"https://quranx.com/Hadith/Nasai/DarusSalam/Volume-4/Book-26/Hadith-3257","x":"It was narrated from 'Aishah that the Messenger of Allah married her when she was six years old, and consummated the marriage with her when she was nine.","ar":"أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا أَبُو مُعَاوِيَةَ، قَالَ حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم تَزَوَّجَهَا وَهِيَ بِنْتُ سِتٍّ وَبَنَى بِهَا وَهِيَ بِنْتُ تِسْعٍ ‏.‏","v":[]},{"c":"Sunan an-Nasa'i","r":"Volume 4, Book 26, Hadith 3258","u":"https://quranx.com/Hadith/Nasai/DarusSalam/Volume-4/Book-26/Hadith-3258","x":"It was narrated that 'Aishah said:\n\n\"The Messenger of Allah married me when I was seven years old, and he consummated the marriage with me when I was nine.\"","ar":"أَخْبَرَنَا مُحَمَّدُ بْنُ النَّضْرِ بْنِ مُسَاوِرٍ، قَالَ حَدَّثَنَا جَعْفَرُ بْنُ سُلَيْمَانَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ تَزَوَّجَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم لِسَبْعِ سِنِينَ وَدَخَلَ عَلَىَّ لِتِسْعِ سِنِينَ ‏.‏","v":[]},{"c":"Sunan an-Nasa'i","r":"Volume 4, Book 26, Hadith 3380","u":"https://quranx.com/Hadith/Nasai/DarusSalam/Volume-4/Book-26/Hadith-3380","x":"It was narrated that 'Aishah said:\n\n\"The Messenger of Allah married me when I was six, and consummated the marriage with me when I was nine, and I used to play with dolls.\"","ar":"أَخْبَرَنَا مُحَمَّدُ بْنُ آدَمَ، عَنْ عَبْدَةَ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ تَزَوَّجَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَنَا بِنْتُ سِتٍّ وَدَخَلَ عَلَىَّ وَأَنَا بِنْتُ تِسْعِ سِنِينَ وَكُنْتُ أَلْعَبُ بِالْبَنَاتِ ‏.‏","v":[]},{"c":"Sunan an-Nasa'i","r":"Volume 4, Book 26, Hadith 3381","u":"https://quranx.com/Hadith/Nasai/DarusSalam/Volume-4/Book-26/Hadith-3381","x":"It was narrated that 'Aishah said:\n\n\"The Messenger of Allah married me when I was six, and consummated the marriage with me when I was nine.\"","ar":"أَخْبَرَنَا أَحْمَدُ بْنُ سَعْدِ بْنِ الْحَكَمِ بْنِ أَبِي مَرْيَمَ، قَالَ حَدَّثَنَا عَمِّي، قَالَ حَدَّثَنَا يَحْيَى بْنُ أَيُّوبَ، قَالَ أَخْبَرَنِي عُمَارَةُ بْنُ غَزِيَّةَ، عَنْ مُحَمَّدِ بْنِ إِبْرَاهِيمَ، عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ عَائِشَةَ، قَالَتْ تَزَوَّجَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم وَهِيَ بِنْتُ سِتِّ سِنِينَ وَبَنَى بِهَا وَهِيَ بِنْتُ تِسْعٍ ‏.‏","v":[]}]};